  "claim": {
    "component_id": "C015.component",
    "value": "Staff recollections should be treated as investigative leads rather than as equivalent to contemporaneous documentation.",
    "scope": "The evidentiary treatment of recollections obtained during clarification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P012 directly supplies the stated treatment of staff recollections."
    }
  },
  "signal_basis": {
    "component_id": "C015.signal_basis",
    "value": "Investigate documentary discrepancies through record requests and staff clarification, checking whether approval records link to the relevant order, precede placement and demonstrate appropriate authority.",
    "scope": "The proposed investigation of sampled orders, assuming its execution and observations; no completed findings are asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
